    timeline.onscroll=()=>{sync(timeline,scrollbar);syncVertical(timeline,fixedColumn);planningVirtualState.scrollLeft=timeline.scrollLeft;planningVirtualState.scrollTop=timeline.scrollTop;planningVirtualState.viewportWidth=timeline.clientWidth;planningVirtualState.viewportHeight=timeline.clientHeight||760;const matrix=document.querySelector('.planning-matrix-shell'),compactView=view==='month'||view==='sixWeeks'||view==='quarter',rowHeight=planningFullscreen&&compactView?64:compactView?74:92,columnWidth=view==='day'?260:view==='week'?170:view==='quarter'?76:104,totalRows=Number(matrix?.dataset.totalRows),totalColumns=Number(matrix?.dataset.totalColumns),rowNeedsRender=planningVirtualWindowNeedsRender(Number(matrix?.dataset.virtualRowStart),Number(matrix?.dataset.virtualRowEnd),totalRows,Math.max(0,timeline.scrollTop-62),planningVirtualState.viewportHeight,rowHeight),columnNeedsRender=planningVirtualWindowNeedsRender(Number(matrix?.dataset.virtualColumnStart),Number(matrix?.dataset.virtualColumnEnd),totalColumns,timeline.scrollLeft,planningVirtualState.viewportWidth,columnWidth,1);if(matrix&&(rowNeedsRender||columnNeedsRender)&&!planningVirtualRenderQueued){planningVirtualRenderQueued=true;requestAnimationFrame(()=>{planningVirtualRenderQueued=false;render()})}};
