const bindStockOriginal=bindStock;bindStock=function(){bindStockOriginal();const search=document.querySelector('[data-stock-filter="q"]');if(search)search.oninput=()=>{clearTimeout(stockSearchTimer);stockSearchTimer=setTimeout(()=>{stock.filters.q=search.value;const term=search.value.trim().toLowerCase();document.querySelectorAll('.stock-table tbody tr').forEach(row=>row.hidden=Boolean(term&&!row.textContent.toLowerCase().includes(term)))},220)};if(location.hash.slice(1)==='equipment'&&can('equipment.manage')){const tools=document.createElement('div');tools.className='location-manager';tools.innerHTML=`<label>Emplacement<select aria-label="Emplacement à modifier">${stock.locations.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(stockNameFromStateSite(x.siteId))}</option>`).join('')}</select></label><button type="button" class="secondary-button">Modifier</button>`;tools.querySelector('button').onclick=()=>openStockDrawer('location',tools.querySelector('select').value);document.querySelector('.stock-toolbar')?.append(tools)}if(location.hash.slice(1)==='stock'&&stock.stockTab==='movements'&&stock.filters.site){document.querySelectorAll('.stock-table tbody tr').forEach(row=>{const sequence=Number(row.querySelector('code')?.textContent.replace('#','')),movement=stock.movements.find(x=>x.sequence===sequence),atSite=movement?.entries?.some(entry=>find(stock.locations,entry.locationId)?.siteId===stock.filters.site);row.hidden=!atSite})}};

const organization={companies:[],current:null,completeness:null,addresses:[],contacts:[],sites:[],units:[],offerings:[],memberships:[],roles:[],fiscalProfile:null,vatRates:[],fiscalUnavailable:false,loading:false,error:'',query:'',status:'',activity:'',dirty:false,eventsBound:false,o1Step:0,o1Validated:0,o1Ceiling:5,vatEditor:null};
const organizationRoutes=new Set(['organizations','organization','organization-new','organization-identity','organization-structure','organization-governance','organization-activation','team']);
const activityLabels={postProduction:'Post-production',rental:'Location',laboratory:'Laboratoire',services:'Services',other:'Autre'};
