function financeMinor(value){const text=String(value||'').replace(',','.');if(!/^\d+(?:\.\d{1,2})?$/.test(text))throw new Error('Montant invalide.');const[whole,fraction='']=text.split('.');return String(BigInt(whole)*100n+BigInt((fraction+'00').slice(0,2)))}
