async function archiveOrganizationFromUi(company){if(!can('organization.archive')||company.status==='archived')return;const name=company.tradeName||company.legalName;if(!confirm(`ATTENTION — Suppression de « ${name} »\n\nL’organisation disparaîtra des espaces actifs. Ses sites, services, ressources et accès ne pourront plus être utilisés.\n\nCette action ne pourra pas être annulée depuis cette interface. L’historique légal sera conservé.\n\nConfirmer la suppression ?`))return;if(company.id!==state.user?.companyId){await switchOrganization(company.id);if(state.user?.companyId!==company.id)return;company=currentOrganization()}const reason=prompt('Indiquez le motif de la suppression (10 caractères minimum).',`Suppression demandée par l’administrateur`);if(!reason)return;try{await api(`/api/v1/companies/${encodeURIComponent(company.id)}`,{method:'DELETE',body:JSON.stringify({version:company.version,confirmation:company.id,reason})});await refreshOrganization(false);location.hash='organizations';render();toast('Organisation supprimée des espaces actifs.')}catch(error){toast(apiMessage(error))}}
async function archiveStructureFromUi(kind,item){const labels={unit:'service interne',offering:'prestation'},routes={unit:'organization-units',offering:'service-offerings'},effects={unit:'Ce service et ses rattachements ne pourront plus être utilisés.',offering:'Cette prestation ne pourra plus être sélectionnée.'};if(!confirm(`ATTENTION — Suppression du ${labels[kind]} « ${item.name} »\n\n${effects[kind]}\n\nCette action ne pourra pas être annulée depuis cette interface. L’historique sera conservé.\n\nConfirmer la suppression ?`))return;try{await api(`/api/v1/${routes[kind]}/${encodeURIComponent(item.id)}`,{method:'DELETE',body:JSON.stringify({version:item.version})});await refreshOrganization(false);render();toast(`${kind==='unit'?'Service interne':'Prestation'} supprimé des éléments actifs.`)}catch(error){toast(apiMessage(error))}}
async function archiveResourceFromUi(item){if(!confirm(`ATTENTION — Suppression de la ressource « ${item.name} »\n\nLa ressource sera retirée du parc actif et ne pourra plus être utilisée dans le planning.\n\nCette action ne pourra pas être annulée depuis cette interface. L’historique sera conservé.\n\nConfirmer la suppression ?`))return;try{await api(`/api/v1/resources/${encodeURIComponent(item.id)}`,{method:'DELETE',body:JSON.stringify({version:item.version})});state.resources=state.resources.filter(resource=>resource.id!==item.id);render();toast('Ressource supprimée du parc actif.')}catch(error){toast(apiMessage(error))}}
