function applyOrganizationExamples(){const examples={'identity-base':{legalName:'Ex. Eliote Props Prod',tradeName:'Ex. Eliote Post',code:'Ex. ELIOTE_PROPS',registrationCountry:'Ex. FR',defaultTimezone:'Ex. Europe/Paris',locale:'Ex. fr-FR',defaultCountry:'Ex. FR',website:'Ex. https://eliote.fr',activityDescription:'Ex. Post-production image et son',line1:'Ex. 12 rue de la Post-production',postalCode:'Ex. 75011',city:'Ex. Paris',contactName:'Ex. Camille Martin',jobTitle:'Ex. Responsable administratif',email:'Ex. contact@eliote.fr',phone:'Ex. +33 1 42 00 00 00'},site:{name:'Ex. Paris Bastille',code:'Ex. PARIS_BASTILLE',line1:'Ex. 12 rue de la Post-production',postalCode:'Ex. 75011',city:'Ex. Paris',country:'Ex. FR'},unit:{name:'Ex. Service Post-production',code:'Ex. POST_PROD'},offering:{name:'Ex. Montage image',code:'Ex. MONTAGE'},member:{userId:'Ex. user_planner',displayName:'Ex. Camille Martin',jobTitle:'Ex. Responsable planning'}};for(const [kind,fields]of Object.entries(examples)){const form=document.querySelector(`[data-org-form="${kind}"]`);if(!form)continue;for(const [name,value]of Object.entries(fields))if(form.elements[name]&&!form.elements[name].placeholder)form.elements[name].placeholder=value}}
