function appendAdminDeleteButtons(){if(can('organization.archive'))document.querySelectorAll('[data-org-open]').forEach(open=>{const company=organization.companies.find(item=>item.id===open.dataset.orgOpen);if(!company||company.status==='archived'||open.parentElement.querySelector('[data-delete-company]'))return;const button=deleteIconButton(`Supprimer l’organisation ${company.tradeName||company.legalName}`,()=>archiveOrganizationFromUi(company));button.dataset.deleteCompany=company.id;open.parentElement.append(button)});if(location.hash.slice(1)==='organization'&&can('organization.archive')){const company=currentOrganization(),page=document.querySelector('.org-page');if(company&&company.status!=='archived'&&page&&!page.querySelector('[data-delete-company-current]')){const panel=document.createElement('article');panel.className='card danger-zone';panel.innerHTML='<div><strong>Zone d’administration</strong><p>La suppression archive l’organisation et conserve ses documents et historiques.</p></div>';const button=deleteIconButton(`Supprimer l’organisation ${company.tradeName||company.legalName}`,()=>archiveOrganizationFromUi(company));button.dataset.deleteCompanyCurrent='';panel.append(button);page.append(panel)}}const sections=document.querySelectorAll('.org-section');if(can('organizationUnit.manage'))sections[1]?.querySelectorAll('.org-entity-list>div').forEach((row,index)=>{const item=organization.units[index];if(!item)return;row.append(deleteIconButton(`Supprimer le service interne ${item.name}`,()=>archiveStructureFromUi('unit',item)))});if(can('serviceOffering.manage'))sections[2]?.querySelectorAll('.org-entity-list>div').forEach((row,index)=>{const item=organization.offerings[index];if(!item)return;row.append(deleteIconButton(`Supprimer la prestation ${item.name}`,()=>archiveStructureFromUi('offering',item)))})}
