const equipmentCategoryLabels={camera:'Caméra',monitor:'Moniteur',audio:'Audio',storage:'Stockage',workstation:'Station de travail',server:'Serveur',laptop:'Portable professionnel',softwareLicense:'Licence logicielle',emailLicense:'Licence messagerie',lens:'Optique',video:'Vidéo',cable:'Câble',power:'Énergie',support:'Support',equipment:'Matériel'};
const moneyFromMinor=(value,currency='EUR')=>value===undefined||value===null||value===''?'':(Number(value)/100).toLocaleString('fr-FR',{style:'currency',currency});
const minorFromMoney=value=>value===''||value==null?undefined:Math.round(Number(String(value).replace(',','.'))*100);
function technicalSpecsText(specifications={}){return Object.entries(specifications||{}).map(([key,value])=>`${key}: ${value}`).join('\n')}
function technicalSpecsObject(text){const result={};for(const line of String(text||'').split('\n')){const index=line.indexOf(':');if(index>0){const key=line.slice(0,index).trim(),value=line.slice(index+1).trim();if(key&&value)result[key]=value}}return result}
function renderCatalogSuggestions(items=[]){const target=stockDrawerBody.querySelector('[data-catalog-results]');if(!target)return;target.innerHTML=items.length?items.map(item=>`<button type="button" class="catalog-suggestion" data-catalog-id="${esc(item.catalogId)}"><img src="${esc(item.photoUrl)}" alt="Photo de ${esc(item.manufacturer)} ${esc(item.model)}"><span><strong>${esc(item.manufacturer)} ${esc(item.model)}</strong><small>${esc(equipmentCategoryLabels[item.category]||item.category)} · ${esc(item.manufacturerReference)}</small><em>${esc(item.description)}</em>${item.matchReason?`<i>✦ ${esc(item.matchReason)}</i>`:''}</span><b>Choisir</b></button>`).join(''):'<p class="catalog-empty">Aucun résultat. Essayez une marque, un usage (« serveur », « mail », « montage ») ou continuez manuellement.</p>';target.querySelectorAll('[data-catalog-id]').forEach(button=>button.onclick=()=>applyCatalogSuggestion(items.find(item=>item.catalogId===button.dataset.catalogId)))}
function applyCatalogSuggestion(suggestion){if(!suggestion)return;activeStockEditor.catalogSuggestion=suggestion;const fields={catalogId:suggestion.catalogId,name:suggestion.name,sku:suggestion.suggestedSku,category:suggestion.category,trackingMode:suggestion.suggestedTrackingMode||'serialized',manufacturer:suggestion.manufacturer,model:suggestion.model,manufacturerReference:suggestion.manufacturerReference,description:suggestion.description,technicalSpecificationsJson:technicalSpecsText(suggestion.technicalSpecifications)};for(const[name,value]of Object.entries(fields))if(stockDrawerForm.elements[name])stockDrawerForm.elements[name].value=value;const createAsset=stockDrawerForm.elements.createFirstAsset;if(createAsset){createAsset.checked=(suggestion.suggestedTrackingMode||'serialized')==='serialized';createAsset.closest('label').hidden=!createAsset.checked}const preview=stockDrawerBody.querySelector('[data-catalog-preview]');if(preview)preview.innerHTML=`<img src="${esc(suggestion.photoUrl)}" alt="Photo de ${esc(suggestion.manufacturer)} ${esc(suggestion.model)}"><div><span>${suggestion.photoKind?.startsWith('manufacturer')?'Photo fabricant':'Visuel de catégorie'} · données à vérifier</span><strong>${esc(suggestion.manufacturer)} ${esc(suggestion.model)}</strong><small>Catalogue ${esc(suggestion.catalogVersion)}</small>${suggestion.sourceUrl?`<a href="${esc(suggestion.sourceUrl)}" target="_blank" rel="noopener noreferrer">Consulter la source officielle ↗</a>`:''}</div>`;stockDrawerDirty=true}
function enhanceItemDrawer(item){const basic=stockDrawerBody.firstElementChild;basic?.insertAdjacentHTML('beforebegin',`<section class="catalog-assistant"><div class="catalog-assistant-head"><span class="assistant-mark">✦</span><div><strong>Assistant catalogue matériel & licences</strong><small>Recherche intelligente locale · sources fabricant · validation humaine</small></div></div><label>Que recherchez-vous ?<input type="search" data-catalog-search placeholder="Ex. Lenovo, serveur montage, licence Adobe, mail" autocomplete="off"></label><div class="catalog-search-examples" aria-label="Exemples de recherche">${['Lenovo','HP','Dell','Avid','serveur','Adobe','mail'].map(term=>`<button type="button" data-catalog-example="${term}">${term}</button>`).join('')}</div><div class="catalog-results" data-catalog-results aria-live="polite"></div><div class="catalog-preview" data-catalog-preview>${item?.photoUrl?`<img src="${esc(item.photoUrl)}" alt="Photo catalogue ${esc(item.name)}"><div><span>Fiche catalogue liée</span><strong>${esc(item.manufacturer||'')} ${esc(item.model||'')}</strong><small>${esc(item.catalogVersion||'')}</small></div>`:'<p>Saisissez au moins 2 caractères. L’assistant comprend aussi un usage comme « serveur », « mail » ou « montage ».</p>'}</div></section><input type="hidden" name="catalogId" value="${esc(item?.catalogId||'')}"><div class="form-grid equipment-fields"><label>Fabricant<input name="manufacturer" value="${esc(item?.manufacturer||'')}" placeholder="Ex. Lenovo, HP, Dell, Avid"></label><label>Modèle<input name="model" value="${esc(item?.model||'')}" placeholder="Ex. ThinkStation P8"></label></div><label>Référence fabricant<input name="manufacturerReference" value="${esc(item?.manufacturerReference||'')}" placeholder="Ex. 30HH"></label><label>Description technique<textarea name="description" maxlength="2000" placeholder="Usage et caractéristiques principales…">${esc(item?.description||'')}</textarea></label><label>Caractéristiques <small>Une ligne par donnée, sous la forme Nom : valeur</small><textarea name="technicalSpecificationsJson" maxlength="6000" placeholder="Processeur : selon configuration\nMémoire : 128 Go DDR5 ECC\nUsage : montage 4K">${esc(technicalSpecsText(item?.technicalSpecifications))}</textarea></label>${!item?'<label class="checkbox next-asset"><input type="checkbox" name="createFirstAsset" checked> Ajouter le premier exemplaire (série et coûts) juste après</label>':''}`);const search=stockDrawerBody.querySelector('[data-catalog-search]');let timer;const run=()=>{clearTimeout(timer);const q=search.value.trim();if(q.length<2){renderCatalogSuggestions([]);return}timer=setTimeout(async()=>{try{const result=await api(`/api/v1/equipment/catalog/suggestions?q=${encodeURIComponent(q)}&limit=12`);renderCatalogSuggestions(listItems(result))}catch(error){const target=stockDrawerBody.querySelector('[data-catalog-results]');if(target)target.innerHTML=`<p class="catalog-empty">${esc(apiMessage(error))}</p>`}},180)};search.oninput=run;stockDrawerBody.querySelectorAll('[data-catalog-example]').forEach(button=>button.onclick=()=>{search.value=button.dataset.catalogExample;run()})}
function enhanceAssetDrawer(item){const currency=currentOrganization()?.currency||'EUR',condition=stockDrawerForm.elements.condition?.closest('label');condition?.insertAdjacentHTML('beforebegin',`${drawerField('Numéro interne','internalCode',item?.internalCode,'text','maxlength="120" placeholder="Ex. ELI-CAM-001"')}<div class="form-grid equipment-fields"><label>Coût d’achat (${esc(currency)})<input name="purchaseCost" type="number" min="0" step="0.01" value="${item?.purchaseCostMinor==null?'':Number(item.purchaseCostMinor)/100}" placeholder="Ex. 6490,00"></label><label>Valeur de remplacement (${esc(currency)})<input name="replacementValue" type="number" min="0" step="0.01" value="${item?.replacementValueMinor==null?'':Number(item.replacementValueMinor)/100}" placeholder="Ex. 7200,00"></label></div><div class="form-grid equipment-fields"><label>Tarif location / jour (${esc(currency)})<input name="dailyRentalPrice" type="number" min="0" step="0.01" value="${item?.dailyRentalPriceMinor==null?'':Number(item.dailyRentalPriceMinor)/100}" placeholder="Ex. 350,00"></label>${drawerField('Date d’achat','purchaseDate',item?.purchaseDate,'date')}</div>${drawerField('Fournisseur','supplier',item?.supplier,'text','maxlength="240" placeholder="Ex. Visual Impact France"')}${drawerField('Fin de garantie','warrantyEndDate',item?.warrantyEndDate,'date')}<input type="hidden" name="currency" value="${esc(currency)}">`);const selector=stockDrawerForm.elements.stockItemId,preview=document.createElement('div');preview.className='asset-product-preview';selector?.closest('label')?.after(preview);const sync=()=>{const article=find(stock.items,selector?.value);preview.innerHTML=article?`${article.photoUrl?`<img src="${esc(article.photoUrl)}" alt="">`:''}<div><strong>${esc(article.name)}</strong><small>${esc(article.manufacturer||'Saisie manuelle')} · ${esc(article.model||article.sku)}</small></div>`:''};selector?.addEventListener('change',sync);if(activeStockEditor.selectedStockItemId)selector.value=activeStockEditor.selectedStockItemId;sync()}
const openEquipmentAssistantBase=openStockDrawer;
openStockDrawer=function(kind,entityId=''){openEquipmentAssistantBase(kind,entityId);if(kind==='item')enhanceItemDrawer(activeStockEditor.item);if(kind==='asset'){enhanceAssetDrawer(activeStockEditor.item);if(activeStockEditor.selectedStockItemId)stockDrawerForm.elements.stockItemId.value=activeStockEditor.selectedStockItemId}stockDrawerForm.onsubmit=submitProfessionalEquipmentDrawer};
