async function submitProfessionalEquipmentDrawer(event){const editor=activeStockEditor;if(!['item','asset'].includes(editor?.kind))return submitEquipmentBase(event);event.preventDefault();const data=new FormData(stockDrawerForm),form=Object.fromEntries(data),item=editor.item,routeBase=editor.kind==='item'?'/api/v1/stock/items':'/api/v1/equipment/assets';stockDrawerError.hidden=true;stockDrawerSubmit.disabled=true;stockDrawerSubmit.textContent='Enregistrement…';try{let body={...form,...(item?{version:item.version}:{})};if(editor.kind==='item'){body={...body,unit:'piece',active:stockDrawerForm.elements.active.checked,technicalSpecifications:technicalSpecsObject(form.technicalSpecificationsJson)};delete body.technicalSpecificationsJson;delete body.createFirstAsset}else{body={...body,purchaseCostMinor:minorFromMoney(form.purchaseCost),replacementValueMinor:minorFromMoney(form.replacementValue),dailyRentalPriceMinor:minorFromMoney(form.dailyRentalPrice)};delete body.purchaseCost;delete body.replacementValue;delete body.dailyRentalPrice;if(item){delete body.stockItemId;delete body.siteId}}const saved=await api(routeBase+(item?`/${encodeURIComponent(item.id)}`:''),{method:item?'PATCH':'POST',headers:{'Idempotency-Key':editor.idempotencyKey},body:JSON.stringify(body)});await loadStockData();stockDrawerDirty=false;if(editor.kind==='item'&&!item&&data.get('createFirstAsset')){activeStockEditor={kind:'asset',selectedStockItemId:saved.id,idempotencyKey:uid('asset-')};openStockDrawer('asset');activeStockEditor.selectedStockItemId=saved.id;stockDrawerForm.elements.stockItemId.value=saved.id;stockDrawerForm.elements.stockItemId.dispatchEvent(new Event('change'));toast('Article créé. Renseignez maintenant l’exemplaire physique.');return}stockDrawerBackdrop.hidden=true;render();toast(editor.kind==='item'?'Fiche matériel enregistrée.':'Exemplaire et coûts enregistrés.')}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}finally{stockDrawerSubmit.disabled=false;stockDrawerSubmit.textContent='Enregistrer'}}
function resourcesProfessionalPage(){const rooms=state.resources;return`<section class="page resources-page">${title('Ressources','Salles, suites et moyens humains reliés au parc matériel.',can('resource.manage')?'<button data-add="resources" class="primary-button">＋ Nouvelle ressource</button>':'')}<div class="stats resource-kpis">${[['Ressources actives',rooms.length],['Salles et suites',rooms.filter(x=>['room','suite'].includes(x.type)).length],['Matériels installés',rooms.reduce((sum,x)=>sum+Number(x.installedEquipmentCount||0),0)]].map(([label,value])=>`<article class="card stat"><div class="stat-top">${label}</div><div class="stat-value">${value}</div></article>`).join('')}</div><article class="card stock-table-wrap"><table class="data-table resource-table"><thead><tr><th>Ressource</th><th>Type</th><th>Site</th><th>Capacité</th><th>Équipement</th><th>Actions</th></tr></thead><tbody>${rooms.map(resource=>`<tr><td><div class="entity"><span class="entity-icon">${esc(resource.name.slice(0,2))}</span><strong>${esc(resource.name)}</strong></div></td><td>${esc(resource.type)}</td><td>${esc(stockNameFromStateSite(resource.siteId))}</td><td>${resource.capacity}</td><td>${['room','suite'].includes(resource.type)?`<span class="installed-count">${Number(resource.installedEquipmentCount||0)} installé(s)</span>`:'—'}</td><td>${['room','suite'].includes(resource.type)?`<button type="button" class="secondary-button" data-room-equipment="${esc(resource.id)}">Équiper la salle</button>`:''}</td></tr>`).join('')}</tbody></table></article></section>`}
const professionalEntitiesBase=entities;
