async function openRoomEquipmentDrawer(resourceId){const result=await api(`/api/v1/resources/${encodeURIComponent(resourceId)}/equipment`),room=result.room,installed=listItems(result);activeStockEditor={kind:'roomEquipment',room,installed,idempotencyKey:uid('room-')};stockDrawerEyebrow.textContent='RESSOURCE · SALLE';stockDrawerTitle.textContent=room.name;stockDrawerSubmit.hidden=!can('equipment.manage');stockDrawerSubmit.textContent='Installer le matériel';const available=stock.assets.filter(asset=>asset.active&&asset.status==='available'&&!asset.assignedRoomId&&asset.siteId===room.siteId),destinations=stock.locations.filter(location=>location.active&&location.siteId===room.siteId&&location.kind!=='room');stockDrawerBody.innerHTML=`<section class="room-equipment-summary"><div><span>Matériel installé</span><strong>${installed.length}</strong></div><p>Les exemplaires sont sélectionnés depuis le Parc matériel du même site.</p></section><div class="installed-equipment-list">${installed.map(asset=>`<article><div class="equipment-photo-small">${asset.stockItem?.photoUrl?`<img src="${esc(asset.stockItem.photoUrl)}" alt="">`:'▣'}</div><div><strong>${esc(asset.stockItem?.name||asset.serialNumber)}</strong><small>Série ${esc(asset.serialNumber)}${asset.internalCode?` · Interne ${esc(asset.internalCode)}`:''}</small><span>${esc(stockLabel[asset.condition]||asset.condition)}</span></div>${can('equipment.manage')?`<button type="button" class="icon-delete-button danger-button" data-room-unassign="${esc(asset.id)}" aria-label="Déposer ${esc(asset.stockItem?.name||asset.serialNumber)}" title="Déposer de la salle">−</button>`:''}</article>`).join('')||'<p class="catalog-empty">Aucun matériel installé dans cette salle.</p>'}</div>${can('equipment.manage')?`<hr><label>Matériel disponible sur ce site<select name="assetId" ${available.length?'':'disabled'}>${available.map(asset=>`<option value="${esc(asset.id)}">${esc(stockName('items',asset.stockItemId))} · série ${esc(asset.serialNumber)}${asset.internalCode?` · ${esc(asset.internalCode)}`:''}</option>`).join('')}</select></label><label>Motif d’installation<input name="reason" required value="Installation permanente dans ${esc(room.name)}"></label><label>Emplacement de retour en cas de dépose<select name="destinationLocationId">${destinations.map(location=>`<option value="${esc(location.id)}">${esc(location.name)}</option>`).join('')}</select></label>`:''}`;stockDrawerError.hidden=true;stockDrawerBackdrop.hidden=false;stockDrawerForm.onsubmit=submitRoomAssignment;stockDrawerForm.querySelectorAll('[data-room-unassign]').forEach(button=>button.onclick=()=>unassignRoomEquipment(button.dataset.roomUnassign));setTimeout(()=>stockDrawerForm.querySelector('select,input,button')?.focus(),0)}
async function submitRoomAssignment(event){event.preventDefault();const data=Object.fromEntries(new FormData(stockDrawerForm)),asset=find(stock.assets,data.assetId),room=activeStockEditor.room;if(!asset)return;stockDrawerSubmit.disabled=true;try{await api(`/api/v1/resources/${encodeURIComponent(room.id)}/equipment`,{method:'POST',body:JSON.stringify({assetId:asset.id,assetVersion:asset.version,roomVersion:room.version,reason:data.reason})});await Promise.all([loadStockData(),hydrateResourcesOnly()]);await openRoomEquipmentDrawer(room.id);toast('Matériel installé dans la salle.')}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}finally{stockDrawerSubmit.disabled=false}}
async function unassignRoomEquipment(assetId){const data=Object.fromEntries(new FormData(stockDrawerForm)),asset=find(stock.assets,assetId),room=activeStockEditor.room;if(!asset||!data.destinationLocationId||!confirm(`Déposer « ${stockName('items',asset.stockItemId)} » de cette salle ?`))return;try{await api(`/api/v1/resources/${encodeURIComponent(room.id)}/equipment/${encodeURIComponent(asset.id)}`,{method:'DELETE',body:JSON.stringify({assetVersion:asset.version,roomVersion:room.version,destinationLocationId:data.destinationLocationId,reason:`Dépose administrative depuis ${room.name}`})});await Promise.all([loadStockData(),hydrateResourcesOnly()]);await openRoomEquipmentDrawer(room.id);toast('Matériel déposé et replacé en stock.')}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}}
async function hydrateResourcesOnly(){state.resources=listItems(await api('/api/v1/resources?active=true'))}
