function commercialRoute(route){return route==='projects'||route==='quotes'||route.startsWith('quote-')||route.startsWith('project-')}
function decimalToScaledString(value,exponent,fieldLabel){const text=String(value??'').trim().replace(',','.');if(!new RegExp(`^(0|[1-9][0-9]*)(?:\\.([0-9]{0,${exponent}}))?$`).test(text))throw new Error(`${fieldLabel} doit contenir au maximum ${exponent} décimale${exponent>1?'s':''}.`);const[whole,fraction='']=text.split('.');return String(BigInt(whole)*10n**BigInt(exponent)+BigInt((fraction+'0'.repeat(exponent)).slice(0,exponent)||'0'))}
