function formatMinorExact(value,currency='EUR',exponent=2){const digits=String(value??'0'),negative=digits.startsWith('-'),raw=negative?digits.slice(1):digits,padded=raw.padStart(exponent+1,'0'),whole=exponent?padded.slice(0,-exponent):padded,fraction=exponent?padded.slice(-exponent):'',grouped=whole.replace(/\B(?=(\d{3})+(?!\d))/g,' ');return`${negative?'−':''}${grouped}${fraction?`,${fraction}`:''} ${esc(currency)}`}
