async function openQuotePreset(term){await openQuoteLineDrawer();if(activeStockEditor?.kind!=='quoteLine')return;const form=stockDrawerForm,search=form.elements.catalogSearch,select=form.elements.catalogKey,normalizedTerm=String(term).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr-FR'),defaults=term.startsWith('Étalonnage')?{section:'Étalonnage',unit:'jour',cost:'600',price:'900'}:term.startsWith('Mixage')?{section:'Mixage',unit:'jour',cost:'500',price:'750'}:term.startsWith('PAD')?{section:'Livrables',unit:'forfait',cost:'200',price:'350'}:term.startsWith('Stockage NEXIS')?{section:'Stockage',unit:'To/mois',cost:'18',price:'35'}:term.startsWith('Stockage Nearline')?{section:'Stockage',unit:'To/mois',cost:'8',price:'18'}:term.startsWith('Montage')?{section:'Montage',unit:'jour',cost:'250',price:'450'}:{section:'Technique',unit:'jour',cost:'0',price:'0'};if(search){search.value=term;search.dispatchEvent(new Event('input',{bubbles:true}))}const option=[...select.options].find(item=>item.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr-FR').includes(normalizedTerm));if(option){select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}))}else form.elements.label.value=term;if(defaults.section==='Stockage'&&![...form.elements.section.options].some(item=>item.value==='Stockage'))form.elements.section.add(new Option('Stockage','Stockage'));if(defaults.unit==='To/mois'&&![...form.elements.unit.options].some(item=>item.value==='To/mois'))form.elements.unit.add(new Option('To/mois','To/mois'));form.elements.section.value=defaults.section;form.elements.unit.value=defaults.unit;form.elements.costUnit.value=defaults.cost;form.elements.unitPrice.value=defaults.price;form.elements.unitPrice.dataset.manual='true';stockDrawerTitle.textContent=`Ajouter · ${term}`}
