const plany={open:false,conversationId:null,messages:[],sending:false,confirmingProposalId:null,proposalKeys:{},error:'',opener:null};let planyEscapeHandler=null;
function planyActionMarkup(action,index,messageId){if(action.type!=='confirmProposal')return`<button type="button" class="secondary-button" data-plany-action="${index}" data-plany-message="${esc(messageId||'')}">${esc(action.label||'Ouvrir')}</button>`;const preview=action.preview||{},done=action.status==='executed',busy=plany.confirmingProposalId===action.proposalId;return`<section class="plany-proposal" aria-label="Prévisualisation de la réservation"><strong>${esc(preview.title||'Réservation proposée')}</strong><dl><div><dt>Projet</dt><dd>${esc(preview.projectName||'—')}</dd></div><div><dt>Ressource</dt><dd>${esc(preview.resourceName||'—')}</dd></div><div><dt>Début</dt><dd>${esc(preview.startsAt?new Date(preview.startsAt).toLocaleString('fr-FR'):'—')}</dd></div><div><dt>Fin</dt><dd>${esc(preview.endsAt?new Date(preview.endsAt).toLocaleString('fr-FR'):'—')}</dd></div><div><dt>Statut</dt><dd>Option</dd></div></dl>${done?'<p class="plany-proposal-result">✓ Réservation créée après votre confirmation.</p>':`<div class="plany-proposal-actions"><button type="button" class="primary-button" data-plany-confirm="${esc(action.proposalId)}" data-plany-digest="${esc(action.proposalDigest)}" ${busy||!can('planning.write')?'disabled':''}>${busy?'Confirmation…':'Confirmer et créer'}</button><button type="button" class="secondary-button" data-plany-reject="${esc(action.proposalId)}" ${busy?'disabled':''}>Refuser</button></div><small>Les droits, versions et disponibilités seront revérifiés au moment de confirmer.</small>`}</section>`}
function planyPanel(){const messages=plany.messages.length?plany.messages:[{role:'assistant',content:'Bonjour, je suis PlanyBot. Je peux chercher des salles libres, résumer un projet, repérer les conflits ou préparer une réservation.',actions:[]}];return`<button type="button" class="plany-launcher" data-plany-open aria-haspopup="dialog" aria-expanded="${plany.open?'true':'false'}"><span aria-hidden="true">P</span><strong>PlanyBot</strong><small>Assistant Planning</small></button>${plany.open?`<aside class="plany-panel" role="dialog" aria-modal="false" aria-labelledby="plany-title"><header><div><span class="plany-mark" aria-hidden="true">P</span><div><strong id="plany-title">PlanyBot</strong><small>Assistant Planning</small></div></div><button type="button" class="icon-button" data-plany-close aria-label="Fermer PlanyBot">×</button></header><div class="plany-safety"><strong>PlanyBot prépare, vous confirmez.</strong><span>Aucune réservation n’est créée automatiquement.</span></div><div class="plany-messages" data-plany-messages aria-live="polite">${messages.map(message=>`<article class="plany-message ${message.role}"><span>${message.role==='assistant'?'PlanyBot':'Vous'}</span><p>${esc(message.content)}</p>${(message.actions||[]).map((action,index)=>planyActionMarkup(action,index,message.id)).join('')}</article>`).join('')}${plany.sending?'<article class="plany-message assistant is-typing"><span>PlanyBot</span><p>J’analyse le planning…</p></article>':''}</div><div class="plany-prompts" aria-label="Questions rapides"><button type="button" data-plany-prompt="Quelles salles de mixage sont libres cette semaine ?">Salles libres</button><button type="button" data-plany-prompt="Résume le projet actif">Résumé projet</button><button type="button" data-plany-prompt="Y a-t-il des conflits ?">Conflits</button></div>${plany.error?`<p class="plany-error" role="alert">${esc(plany.error)}</p>`:''}<form class="plany-compose" data-plany-form><label for="plany-input">Votre question</label><div><textarea id="plany-input" name="message" rows="2" maxlength="800" placeholder="Ex. Prépare une salle de mixage pour ce projet demain" required></textarea><button type="submit" class="primary-button" ${plany.sending?'disabled':''}>Envoyer</button></div></form></aside>`:''}`}
const planningPlanyBase=planning;
planning=function(){return planningPlanyBase()+planyPanel()}
function closePlany(){const opener=plany.opener;plany.open=false;if(planyEscapeHandler)document.removeEventListener('keydown',planyEscapeHandler);planyEscapeHandler=null;render();setTimeout(()=>{if(opener?.isConnected)opener.focus({preventScroll:true});else document.querySelector('[data-plany-open]')?.focus({preventScroll:true})},0)}
async function sendPlany(message){const text=String(message||'').trim();if(!text||plany.sending)return;plany.messages.push({id:uid('plany-local-user-'),role:'user',content:text,actions:[]});plany.sending=true;plany.error='';render();try{const response=await api('/api/v1/plany/messages',{method:'POST',headers:{'Idempotency-Key':uid('plany-')},body:JSON.stringify({message:text,conversationId:plany.conversationId,context:{...(activePlanningProjectId||filters.project?{projectId:activePlanningProjectId||filters.project}:{}),...(filters.site?{siteId:filters.site}:{})}})});plany.conversationId=response.conversationId;plany.messages.push({id:response.assistant?.id||uid('plany-local-assistant-'),role:'assistant',content:response.assistantMessage,actions:response.actions||[]})}catch(error){plany.error=apiMessage(error)}finally{plany.sending=false;render();setTimeout(()=>{const box=document.querySelector('[data-plany-messages]');if(box)box.scrollTop=box.scrollHeight},0)}}
function preparePlanyAction(action){if(action.type==='openProjectPlanning'){filters.project=action.projectId||'';filters.resource='';activePlanningProjectId=action.projectId||activePlanningProjectId;plany.open=false;render();return}if(action.type!=='prepareBooking')return;filters.project=action.projectId||filters.project;activePlanningProjectId=action.projectId||activePlanningProjectId;anchor=action.startDate||anchor;plany.open=false;render();openBooking('',{projectId:action.projectId,date:action.startDate,resourceId:action.resourceId});if(bookingForm?.elements){bookingForm.elements.title.value=action.title||'';bookingForm.elements.endDate.value=action.endDate||action.startDate;bookingForm.elements.project.value=action.projectId||bookingForm.elements.project.value}toast('PlanyBot a prérempli le formulaire. Vérifiez puis confirmez vous-même.')}
async function confirmPlanyProposal(proposalId,proposalDigest){if(plany.confirmingProposalId)return;const key=plany.proposalKeys[`confirm:${proposalId}`]||(plany.proposalKeys[`confirm:${proposalId}`]=uid('plany-confirm-'));plany.confirmingProposalId=proposalId;plany.error='';render();try{const result=await api(`/api/v1/plany/proposals/${encodeURIComponent(proposalId)}/confirm`,{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify({proposalDigest})});const reservation=fromApiReservation(result.reservation);if(!state.bookings.some(value=>value.id===reservation.id))state.bookings.push(reservation);for(const message of plany.messages)for(const action of message.actions||[])if(action.proposalId===proposalId)action.status='executed';toast('Réservation créée après votre confirmation.')}catch(error){plany.error=apiMessage(error)}finally{plany.confirmingProposalId=null;render()}}
async function rejectPlanyProposal(proposalId){if(plany.confirmingProposalId)return;const key=plany.proposalKeys[`reject:${proposalId}`]||(plany.proposalKeys[`reject:${proposalId}`]=uid('plany-reject-'));plany.confirmingProposalId=proposalId;plany.error='';render();try{await api(`/api/v1/plany/proposals/${encodeURIComponent(proposalId)}/reject`,{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify({reason:'Refus explicite dans le panneau PlanyBot'})});for(const message of plany.messages)message.actions=(message.actions||[]).filter(action=>action.proposalId!==proposalId);toast('Proposition refusée. Aucune réservation créée.')}catch(error){plany.error=apiMessage(error)}finally{plany.confirmingProposalId=null;render()}}
const bindPlanyBase=bind;
bind=function(){bindPlanyBase();if(location.hash.slice(1)!=='planning')return;document.querySelector('[data-plany-open]')?.addEventListener('click',event=>{plany.opener=event.currentTarget;plany.open=true;render();setTimeout(()=>document.querySelector('#plany-input')?.focus(),0)});document.querySelector('[data-plany-close]')?.addEventListener('click',closePlany);document.querySelector('[data-plany-form]')?.addEventListener('submit',event=>{event.preventDefault();const input=event.currentTarget.elements.message;sendPlany(input.value)});document.querySelectorAll('[data-plany-prompt]').forEach(button=>button.addEventListener('click',()=>sendPlany(button.dataset.planyPrompt)));document.querySelectorAll('[data-plany-action]').forEach(button=>button.addEventListener('click',()=>{const message=plany.messages.find(value=>value.id===button.dataset.planyMessage),action=message?.actions?.[Number(button.dataset.planyAction)];if(action)preparePlanyAction(action)}));document.querySelectorAll('[data-plany-confirm]').forEach(button=>button.addEventListener('click',()=>confirmPlanyProposal(button.dataset.planyConfirm,button.dataset.planyDigest)));document.querySelectorAll('[data-plany-reject]').forEach(button=>button.addEventListener('click',()=>rejectPlanyProposal(button.dataset.planyReject)));if(planyEscapeHandler)document.removeEventListener('keydown',planyEscapeHandler);planyEscapeHandler=null;if(plany.open){planyEscapeHandler=event=>{if(event.key==='Escape'){event.preventDefault();closePlany()}};document.addEventListener('keydown',planyEscapeHandler)}}

// Clients 05 — comptes, contacts et grilles tarifaires privées.
const clientsModule={active:null,rates:null,loading:false,error:''};
function clientStatusLabel(value){return value==='prospect'?'Prospect':value==='inactive'?'Inactif':'Actif'}
function clientsProfessionalPage(){return`<section class="page clients-page">${title('Clients','Comptes, contacts et conditions commerciales propres à votre organisation.',can('client.manage')?'<button class="primary-button" data-client-new>＋ Nouveau client</button>':'')}<div class="clients-kpis"><article class="card"><span>Comptes actifs</span><strong>${state.clients.filter(value=>value.active!==false).length}</strong></article><article class="card"><span>Contacts renseignés</span><strong>${state.clients.reduce((sum,value)=>sum+Number(value.contactCount||0),0)}</strong></article><article class="card"><span>Grilles dédiées</span><strong>${state.clients.filter(value=>value.hasDedicatedRates).length}</strong></article></div><article class="card clients-list"><header><div><p class="eyebrow">RÉFÉRENTIEL CLIENT</p><h2>Comptes clients</h2></div><label>Rechercher<input type="search" data-client-search placeholder="Ex. Studio 89, TF1…"></label></header><div class="clients-cards" data-clients-list>${state.clients.map(client=>`<a class="client-card" href="#client-${esc(client.id)}" data-client-row="${esc(`${client.name} ${client.code}`.toLowerCase())}"><span class="entity-icon">${esc(client.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(client.name)}</strong><small>${esc(client.code)} · ${client.contactCount||0} contact(s)</small></div><span class="pill ${client.active===false?'cancelled':'confirmed'}">${client.active===false?'○':'●'} ${clientStatusLabel(client.status)}</span>${client.hasDedicatedRates?'<b class="client-rate-badge">Tarifs dédiés</b>':''}</a>`).join('')||'<p class="empty-cell">Aucun client. Créez le premier compte.</p>'}</div></article></section>`}
function clientDetailProfessionalPage(client){if(!client)return`<section class="page clients-page"><div class="stock-state ${clientsModule.error?'error':''}"><h1>${clientsModule.loading?'Chargement…':'Client introuvable'}</h1><p>${esc(clientsModule.error||'')}</p></div></section>`;const contacts=(client.contacts||[]).filter(value=>value.active!==false),cards=client.rateCards||[];return`<section class="page clients-page client-detail-page">${title(client.name,`${client.code} · ${clientStatusLabel(client.status)}`,`<a class="secondary-button link-button" href="#clients">← Tous les clients</a>${can('client.manage')?'<button class="secondary-button" data-client-edit>Modifier le compte</button>':''}`)}<div class="client-detail-grid"><article class="card client-identity-card"><p class="eyebrow">COMPTE CLIENT</p><h2>Identité et facturation</h2><dl><div><dt>Email général</dt><dd>${esc(client.email||'Non renseigné')}</dd></div><div><dt>Email facturation</dt><dd>${esc(client.billingEmail||'Non renseigné')}</dd></div><div><dt>Téléphone</dt><dd>${esc(client.phone||'Non renseigné')}</dd></div><div><dt>Adresse</dt><dd>${esc([client.billingAddressLine1,client.billingAddressLine2,client.billingPostalCode,client.billingCity,client.billingCountry].filter(Boolean).join(' · ')||'Non renseignée')}</dd></div><div><dt>Site web</dt><dd>${client.website?`<a href="${esc(client.website)}" target="_blank" rel="noopener">${esc(client.website)}</a>`:'Non renseigné'}</dd></div></dl>${client.notes?`<p class="client-notes">${esc(client.notes)}</p>`:''}</article><article class="card client-rates-card"><header><div><p class="eyebrow">CONDITIONS COMMERCIALES</p><h2>Grille tarifaire</h2></div>${can('client.manage')?'<button class="secondary-button" data-client-rate-import>Importer Excel</button>':''}</header>${cards.length?`<div class="client-rate-current"><span>✓ Grille active</span><strong>${esc(cards[0].name)}</strong><small>${cards[0].rateCount} tarif(s) · priorité automatique dans les devis</small><a class="primary-button link-button" href="#client-rates-${esc(client.id)}">Voir les tarifs →</a></div>`:'<div class="client-rate-empty"><strong>Tarifs catalogue appliqués</strong><span>Importez une grille Excel pour utiliser automatiquement les prix négociés de ce client.</span></div>'}</article></div><article class="card client-contacts-card"><header><div><p class="eyebrow">INTERLOCUTEURS</p><h2>Contacts</h2><span>Choisissez l’un de ces contacts lors de la création d’un devis.</span></div>${can('client.manage')?'<button class="primary-button" data-client-contact-new>＋ Ajouter un contact</button>':''}</header><div class="client-contact-grid">${contacts.map(contact=>`<article><div class="client-contact-avatar">${esc(`${contact.firstName[0]||''}${contact.lastName[0]||''}`.toUpperCase())}</div><div><strong>${esc(contact.firstName)} ${esc(contact.lastName)}</strong><span>${esc(contact.jobTitle||'Fonction non renseignée')}</span><a href="mailto:${esc(contact.email)}">${esc(contact.email)}</a>${contact.phone?`<a href="tel:${esc(contact.phone)}">${esc(contact.phone)}</a>`:''}</div>${can('client.manage')?`<div class="client-contact-actions"><button class="icon-button" data-client-contact-edit="${esc(contact.id)}" aria-label="Modifier ${esc(contact.firstName)} ${esc(contact.lastName)}">✎</button><button class="icon-button danger" data-client-contact-delete="${esc(contact.id)}" aria-label="Supprimer ${esc(contact.firstName)} ${esc(contact.lastName)}">−</button></div>`:''}</article>`).join('')||'<p class="empty-cell">Aucun contact. Vous pourrez en ajouter à tout moment.</p>'}</div></article></section>`}
function clientRateCategoryLabel(value){return({laboratory:'Stockage MAM et laboratoire',editing:'Montage',grading:'Étalonnage',mixing:'Mixage',pad:'PAD et livraison',other:'Post-production et logistique',resource:'Salles et ressources',stockItem:'Matériel',serviceOffering:'Prestations'})[value]||value||'Prestations'}
function clientRatesProfessionalPage(data){if(!data)return`<section class="page clients-page"><div class="stock-state ${clientsModule.error?'error':''}"><h1>${clientsModule.loading?'Chargement…':'Grille introuvable'}</h1><p>${esc(clientsModule.error||'')}</p></div></section>`;const items=data.items||[],units=[...new Set(items.map(value=>value.unit))].sort((a,b)=>a.localeCompare(b,'fr'));return`<section class="page clients-page client-rates-page">${title(`Tarifs · ${data.client.name}`,data.rateCard?`${data.rateCard.name} · ${items.length} tarif(s)`:'Aucune grille active',`<a class="secondary-button link-button" href="#client-${esc(data.client.id)}">← Retour à la fiche client</a>`)}<article class="card client-rates-toolbar"><label>Rechercher une prestation<input type="search" data-client-rate-search placeholder="Ex. montage, stockage, PAD…"></label><label>Unité<select data-client-rate-unit><option value="">Toutes les unités</option>${units.map(unit=>`<option value="${esc(unit)}">${esc(unit[0].toUpperCase()+unit.slice(1))}</option>`).join('')}</select></label><div><span>Tarifs actifs</span><strong>${items.length}</strong></div></article><article class="card client-rates-table-card"><div class="table-scroll"><table class="client-rates-table"><thead><tr><th>Service</th><th>Désignation</th><th>Unité</th><th class="numeric">Prix HT</th></tr></thead><tbody>${items.map(item=>`<tr data-client-rate-item data-search="${esc(`${clientRateCategoryLabel(item.category)} ${item.label} ${item.code} ${item.unit}`.toLowerCase())}" data-unit="${esc(item.unit)}"><td><span class="client-rate-section">${esc(clientRateCategoryLabel(item.category))}</span></td><td><strong>${esc(item.label)}</strong>${item.code?`<small>${esc(item.code)}</small>`:''}</td><td><span class="pill">${esc(item.unit)}</span></td><td class="numeric"><strong>${formatMinorExact(item.saleUnitMinor,data.currency,data.currencyExponent)}</strong></td></tr>`).join('')||'<tr><td colspan="4" class="empty-cell">Aucun tarif actif pour ce client.</td></tr>'}</tbody></table></div><p class="client-rate-note">Ces prix sont proposés automatiquement dans les nouveaux devis de ce client. Un tarif projet reste prioritaire.</p></article></section>`}
async function loadClientDetail(idValue){clientsModule.loading=true;clientsModule.error='';render();try{clientsModule.active=await api(`/api/v1/clients/${encodeURIComponent(idValue)}`)}catch(error){clientsModule.active=null;clientsModule.error=apiMessage(error)}finally{clientsModule.loading=false;render()}}
async function loadClientRates(idValue){clientsModule.loading=true;clientsModule.error='';render();try{clientsModule.rates=await api(`/api/v1/clients/${encodeURIComponent(idValue)}/rates`)}catch(error){clientsModule.rates=null;clientsModule.error=apiMessage(error)}finally{clientsModule.loading=false;render()}}
function openClientAccountDrawer(client){activeStockEditor={kind:'clientAccount',client:client||null,idempotencyKey:uid('client-')};stockDrawerEyebrow.textContent='CLIENTS 05';stockDrawerTitle.textContent=client?'Modifier le compte client':'Nouveau client';stockDrawerSubmit.hidden=false;stockDrawerSubmit.disabled=false;stockDrawerSubmit.textContent=client?'Enregistrer':'Créer le compte';stockDrawerError.hidden=true;stockDrawerBody.innerHTML=`<div class="drawer-info"><strong>Informations essentielles</strong><span>Les exemples indiquent le format attendu et ne sont jamais enregistrés.</span></div><div class="form-grid"><label>Nom / raison sociale <b>*</b><input name="name" required maxlength="160" value="${inputValue(client?.name)}" placeholder="Ex. Studio 89 Production"></label><label>Code interne <b>*</b><input name="code" required maxlength="32" pattern="[A-Za-z0-9_-]+" value="${inputValue(client?.code)}" placeholder="Ex. STUDIO89"></label><label>Statut<select name="status"><option value="active" ${client?.status!=='prospect'&&client?.status!=='inactive'?'selected':''}>Actif</option><option value="prospect" ${client?.status==='prospect'?'selected':''}>Prospect</option><option value="inactive" ${client?.status==='inactive'?'selected':''}>Inactif</option></select></label><label>Devise de facturation <b>*</b><select name="currency"><option value="EUR" ${client?.currency!=='USD'&&client?.currency!=='GBP'?'selected':''}>EUR</option><option value="USD" ${client?.currency==='USD'?'selected':''}>USD</option><option value="GBP" ${client?.currency==='GBP'?'selected':''}>GBP</option></select></label><label>Délai de paiement (jours) <b>*</b><input type="number" name="paymentTermsDays" min="0" max="365" value="${inputValue(client?.paymentTermsDays??30)}" required></label><label>Conditions de facturation <b>*</b><input name="billingTerms" maxlength="1000" value="${inputValue(client?.billingTerms||'Paiement à 30 jours date de facture.')}" required></label><label>Email général<input type="email" name="email" value="${inputValue(client?.email)}" placeholder="contact@studio89.fr"></label><label>Téléphone<input type="tel" name="phone" value="${inputValue(client?.phone)}" placeholder="+33 1 40 00 00 00"></label><label>Site web HTTPS<input type="url" name="website" value="${inputValue(client?.website)}" placeholder="https://www.studio89.fr"></label><label>Email de facturation<input type="email" name="billingEmail" value="${inputValue(client?.billingEmail)}" placeholder="facturation@studio89.fr"></label><label>Adresse de facturation<input name="billingAddressLine1" value="${inputValue(client?.billingAddress?.line1||client?.billingAddressLine1)}" placeholder="Ex. 12 rue de la Production"></label><label>Complément<input name="billingAddressLine2" value="${inputValue(client?.billingAddress?.line2||client?.billingAddressLine2)}" placeholder="Bâtiment B"></label><label>Code postal<input name="billingPostalCode" value="${inputValue(client?.billingAddress?.postalCode||client?.billingPostalCode)}" placeholder="75015"></label><label>Ville<input name="billingCity" value="${inputValue(client?.billingAddress?.city||client?.billingCity)}" placeholder="Paris"></label><label>Pays (ISO)<input name="billingCountry" maxlength="2" value="${inputValue(client?.billingAddress?.country||client?.billingCountry||'FR')}" placeholder="FR"></label></div><label>Notes internes<textarea name="notes" maxlength="4000" placeholder="Ex. Bon de commande requis avant facturation">${inputValue(client?.notes)}</textarea></label>`;stockDrawerBackdrop.hidden=false;stockDrawerForm.onsubmit=submitClientAccount;setTimeout(()=>stockDrawerForm.elements.name?.focus(),0)}
async function submitClientAccount(event){event.preventDefault();const editor=activeStockEditor,data=Object.fromEntries(new FormData(stockDrawerForm));stockDrawerSubmit.disabled=true;try{const item=await api(`/api/v1/clients${editor.client?`/${encodeURIComponent(editor.client.id)}`:''}`,{method:editor.client?'PATCH':'POST',headers:editor.client?{}:{'Idempotency-Key':editor.idempotencyKey},body:JSON.stringify({...data,...(editor.client?{version:editor.client.version}:{})})});const existing=find(state.clients,item.id);existing?Object.assign(existing,item):state.clients.push(item);stockDrawerBackdrop.hidden=true;clientsModule.active=editor.client?await api(`/api/v1/clients/${encodeURIComponent(item.id)}`):null;location.hash=editor.client?`client-${item.id}`:'clients';render();toast(editor.client?'Compte client mis à jour.':'Compte client créé.')}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}finally{stockDrawerSubmit.disabled=false}}
function openClientContactDrawer(contact){const client=clientsModule.active;activeStockEditor={kind:'clientContact',client,contact:contact||null,idempotencyKey:uid('client-contact-')};stockDrawerEyebrow.textContent='CONTACT CLIENT';stockDrawerTitle.textContent=contact?'Modifier le contact':'Ajouter un contact';stockDrawerSubmit.hidden=false;stockDrawerSubmit.disabled=false;stockDrawerSubmit.textContent=contact?'Enregistrer':'Ajouter le contact';stockDrawerError.hidden=true;stockDrawerBody.innerHTML=`<div class="form-grid"><label>Prénom <b>*</b><input name="firstName" required maxlength="100" value="${inputValue(contact?.firstName)}" placeholder="Ex. Marie"></label><label>Nom <b>*</b><input name="lastName" required maxlength="100" value="${inputValue(contact?.lastName)}" placeholder="Ex. Dupont"></label><label>Poste chez le client<input name="jobTitle" maxlength="160" value="${inputValue(contact?.jobTitle)}" placeholder="Ex. Directrice de production"></label><label>Adresse email <b>*</b><input type="email" name="email" required maxlength="254" value="${inputValue(contact?.email)}" placeholder="marie.dupont@client.fr"></label><label>Téléphone <small>(facultatif)</small><input type="tel" name="phone" maxlength="40" value="${inputValue(contact?.phone)}" placeholder="+33 6 00 00 00 00"></label></div>`;stockDrawerBackdrop.hidden=false;stockDrawerForm.onsubmit=submitClientContact;setTimeout(()=>stockDrawerForm.elements.firstName?.focus(),0)}
async function submitClientContact(event){event.preventDefault();const editor=activeStockEditor,data=Object.fromEntries(new FormData(stockDrawerForm));stockDrawerSubmit.disabled=true;try{await api(`/api/v1/clients/${encodeURIComponent(editor.client.id)}/contacts${editor.contact?`/${encodeURIComponent(editor.contact.id)}`:''}`,{method:editor.contact?'PATCH':'POST',headers:editor.contact?{}:{'Idempotency-Key':editor.idempotencyKey},body:JSON.stringify({...data,...(editor.contact?{version:editor.contact.version}:{clientVersion:editor.client.version})})});stockDrawerBackdrop.hidden=true;await loadClientDetail(editor.client.id);toast(editor.contact?'Contact mis à jour.':'Contact ajouté.')}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}finally{stockDrawerSubmit.disabled=false}}
async function deleteClientContact(contact){if(!confirm(`Supprimer le contact ${contact.firstName} ${contact.lastName} ?\n\nIl ne sera plus proposé sur les nouveaux devis. Les devis historiques conserveront leur copie du contact.`))return;try{await api(`/api/v1/clients/${encodeURIComponent(clientsModule.active.id)}/contacts/${encodeURIComponent(contact.id)}`,{method:'DELETE',body:JSON.stringify({version:contact.version})});await loadClientDetail(clientsModule.active.id);toast('Contact supprimé du compte.')}catch(error){toast(apiMessage(error))}}
function openClientRateDrawer(){const client=clientsModule.active;activeStockEditor={kind:'clientRates',client,idempotencyKey:uid('client-rates-'),file:null,base64:null,preview:null};stockDrawerEyebrow.textContent='TARIFS CLIENT';stockDrawerTitle.textContent='Importer une grille Excel';stockDrawerSubmit.hidden=false;stockDrawerSubmit.disabled=true;stockDrawerSubmit.textContent='Analyser le fichier';stockDrawerError.hidden=true;stockDrawerBody.innerHTML=`<div class="drawer-info"><strong>${esc(client.name)}</strong><span>Formats reconnus : tableau normalisé ou blocs Stockage MAM, Postproduction et Logistique avec tarifs Heure, Jour, Semaine, Mois et Forfait. La colonne Remise est toujours ignorée.</span></div><label class="client-rate-drop"><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" data-client-rate-file><strong>Choisir la grille tarifaire Excel</strong><span data-client-rate-name>Aucun fichier sélectionné · 5 Mo maximum</span></label><div data-client-rate-preview></div><p class="client-rate-privacy">Le fichier n’est conservé qu’après votre confirmation. Il reste privé, local et traçable.</p>`;stockDrawerBackdrop.hidden=false;stockDrawerForm.onsubmit=previewClientRates;stockDrawerBody.querySelector('[data-client-rate-file]').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(!/\.xlsx$/i.test(file.name)||file.size>5*1024*1024){stockDrawerError.textContent=!/\.xlsx$/i.test(file.name)?'Choisissez un fichier Excel .xlsx.':'Le fichier dépasse 5 Mo.';stockDrawerError.hidden=false;return}activeStockEditor.file=file;activeStockEditor.base64=await clientPlanningBase64(file);stockDrawerBody.querySelector('[data-client-rate-name]').textContent=`${file.name} · ${Math.ceil(file.size/1024)} Ko`;stockDrawerSubmit.disabled=false};setTimeout(()=>stockDrawerBody.querySelector('[data-client-rate-file]')?.focus(),0)}
async function previewClientRates(event){event.preventDefault();const editor=activeStockEditor;if(editor.preview)return confirmClientRates();stockDrawerSubmit.disabled=true;try{const preview=await api(`/api/v1/clients/${encodeURIComponent(editor.client.id)}/rate-card-import/preview`,{method:'POST',body:JSON.stringify({version:editor.client.version,fileName:editor.file.name,mimeType:editor.file.type,contentBase64:editor.base64})});editor.preview=preview;const target=stockDrawerBody.querySelector('[data-client-rate-preview]');target.innerHTML=`<div class="drawer-info"><strong>${preview.summary.matched} tarif(s) reconnu(s) sur ${preview.summary.total}</strong><span>${preview.format==='service-blocks'?'Lecture par services activée. Remise ignorée. ':''}Les tarifs ambigus ou sans correspondance restent décochés.</span></div><div class="client-rate-preview-list">${preview.rows.map(row=>`<label class="client-rate-preview-row ${row.matchStatus}"><input type="checkbox" data-rate-row="${row.rowNumber}" ${row.matchStatus==='matched'?'checked':''} ${row.candidates.length?'':'disabled'}><span><strong>${row.category?`<small>${esc(row.category)}</small>`:''}${esc(row.label||row.reference)}</strong><small>${esc(row.unit)} · ${row.saleUnitMinor?formatMinorExact(row.saleUnitMinor,preview.currency,preview.currencyExponent):esc(row.error||'Prix invalide')}</small></span><select data-rate-source="${row.rowNumber}" ${row.candidates.length?'':'disabled'}>${row.candidates.map(candidate=>`<option value="${esc(`${candidate.sourceType}|${candidate.sourceId}`)}">${esc(candidate.label)}</option>`).join('')}</select></label>`).join('')}</div>`;stockDrawerSubmit.textContent=preview.summary.matched?'Confirmer et activer la grille':'Aucun tarif activable';stockDrawerSubmit.disabled=!preview.rows.some(row=>row.matchStatus==='matched')}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}finally{if(!editor.preview)stockDrawerSubmit.disabled=false}}
async function confirmClientRates(){const editor=activeStockEditor,rows=[...stockDrawerBody.querySelectorAll('[data-rate-row]:checked')].map(input=>{const[sourceType,sourceId]=stockDrawerBody.querySelector(`[data-rate-source="${input.dataset.rateRow}"]`).value.split('|');return{rowNumber:Number(input.dataset.rateRow),sourceType,sourceId}});if(!rows.length){stockDrawerError.textContent='Sélectionnez au moins une ligne reconnue.';stockDrawerError.hidden=false;return}stockDrawerSubmit.disabled=true;try{await api(`/api/v1/clients/${encodeURIComponent(editor.client.id)}/rate-card-imports`,{method:'POST',headers:{'Idempotency-Key':editor.idempotencyKey},body:JSON.stringify({version:editor.client.version,fileName:editor.file.name,mimeType:editor.file.type,contentBase64:editor.base64,rows})});stockDrawerBackdrop.hidden=true;await loadClientDetail(editor.client.id);toast('Grille tarifaire client activée. Elle sera prioritaire dans les nouveaux devis.')}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}finally{stockDrawerSubmit.disabled=false}}
function bindClientsProfessional(){document.querySelector('[data-client-new]')?.addEventListener('click',()=>openClientAccountDrawer());document.querySelector('[data-client-edit]')?.addEventListener('click',()=>openClientAccountDrawer(clientsModule.active));document.querySelector('[data-client-contact-new]')?.addEventListener('click',()=>openClientContactDrawer());document.querySelectorAll('[data-client-contact-edit]').forEach(button=>button.addEventListener('click',()=>openClientContactDrawer(clientsModule.active.contacts.find(value=>value.id===button.dataset.clientContactEdit))));document.querySelectorAll('[data-client-contact-delete]').forEach(button=>button.addEventListener('click',()=>deleteClientContact(clientsModule.active.contacts.find(value=>value.id===button.dataset.clientContactDelete))));document.querySelector('[data-client-rate-import]')?.addEventListener('click',openClientRateDrawer);const search=document.querySelector('[data-client-search]');if(search)search.oninput=()=>document.querySelectorAll('[data-client-row]').forEach(row=>row.hidden=!row.dataset.clientRow.includes(search.value.toLowerCase()))}
function bindClientRatesProfessional(){const search=document.querySelector('[data-client-rate-search]'),unit=document.querySelector('[data-client-rate-unit]'),filter=()=>document.querySelectorAll('[data-client-rate-item]').forEach(row=>{row.hidden=Boolean(search?.value&&!row.dataset.search.includes(search.value.toLowerCase()))||Boolean(unit?.value&&row.dataset.unit!==unit.value)});search?.addEventListener('input',filter);unit?.addEventListener('change',filter)}
const renderClientsProfessionalBase=render;
render=function(){const route=typeof location==='undefined'?'':location.hash.slice(1),ratesRoute=route.startsWith('client-rates-');if(!state.user||!(route==='clients'||route.startsWith('client-')))return renderClientsProfessionalBase();loginScreen.hidden=true;pageCrumb.textContent=route==='clients'?'Clients':ratesRoute?'Tarifs client':'Fiche client';document.querySelectorAll('[data-route]').forEach(link=>{const active=link.dataset.route==='clients';link.classList.toggle('active',active);link.toggleAttribute('aria-current',active)});quickCreate.hidden=true;if(ratesRoute){const idValue=route.slice(13);if((!clientsModule.rates||clientsModule.rates.client?.id!==idValue)&&!clientsModule.loading){clientsModule.rates=null;loadClientRates(idValue);return}app.innerHTML=clientRatesProfessionalPage(clientsModule.rates);bindClientRatesProfessional();return}if(route.startsWith('client-')){const idValue=route.slice(7);if((!clientsModule.active||clientsModule.active.id!==idValue)&&!clientsModule.loading){clientsModule.active=null;loadClientDetail(idValue);return}app.innerHTML=clientDetailProfessionalPage(clientsModule.active)}else app.innerHTML=clientsProfessionalPage();bindClientsProfessional()};
const openQuoteCreateClientBase=openQuoteCreateDrawer;
openQuoteCreateDrawer=function(projectId,kind='quote',fromPlanning=false){openQuoteCreateClientBase(projectId,kind,fromPlanning);const editor=activeStockEditor,project=find(state.projects,projectId)||state.projects[0],client=find(state.clients,project?.clientId),contactsRequestToken=uid('quote-contacts-');if(!client||editor?.kind!=='quoteCreate')return;editor.contactsRequestToken=contactsRequestToken;api(`/api/v1/clients/${encodeURIComponent(client.id)}/contacts?active=true&pageSize=200`).then(result=>{if(activeStockEditor!==editor||editor.kind!=='quoteCreate'||editor.contactsRequestToken!==contactsRequestToken||editor.project?.id!==project.id)return;const contacts=listItems(result),kindField=stockDrawerForm.elements.kind?.closest('label');if(stockDrawerForm.elements.contactId)return;kindField?.insertAdjacentHTML('afterend',`<label>Contact destinataire <small>(facultatif)</small><select name="contactId"><option value="">Aucun contact sélectionné</option>${contacts.map(contact=>`<option value="${esc(contact.id)}">${esc(contact.firstName)} ${esc(contact.lastName)} · ${esc(contact.jobTitle||contact.email)}</option>`).join('')}</select><small>${contacts.length?'Le contact sera figé dans cette version du document.':'Ajoutez des contacts depuis la fiche client.'}</small></label>`) }).catch(()=>{})};
submitQuoteCreate=async function(event){event.preventDefault();const data=new FormData(stockDrawerForm),form=Object.fromEntries(data),editor=activeStockEditor;stockDrawerSubmit.disabled=true;stockDrawerError.hidden=true;stockDrawerError.classList.remove('quote-fiscal-blocker');try{const reservationIds=data.getAll('reservationIds'),creationMethod=editor.fromPlanning&&reservationIds.length?'planning':'manual';let quote=await api('/api/v1/quotes',{method:'POST',headers:{'Idempotency-Key':editor.idempotencyKey},body:JSON.stringify({projectId:editor.project.id,siteId:form.siteId||undefined,contactId:form.contactId||undefined,kind:form.kind,creationMethod,title:form.title,taxDate:form.taxDate})});if(reservationIds.length)quote=await api(`/api/v1/quotes/${encodeURIComponent(quote.id)}/import-reservations`,{method:'POST',body:JSON.stringify({version:quote.version,reservationIds})});updateQuoteLocal(quote);stockDrawerDirty=false;stockDrawerBackdrop.hidden=true;location.hash=`quote-${quote.id}`;render();toast(editor.fromPlanning&&reservationIds.length?'Devis créé depuis le planning avec traçabilité de son origine.':'Document manuel créé sans réservation automatique.')}catch(error){if(error.code==='FISCAL_PROFILE_INCOMPLETE')showQuoteFiscalBlocker(error);else{stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}}finally{stockDrawerSubmit.disabled=false}};
const quoteA4ClientsBase=quoteA4Workspace;
