const bindCommercialSynopticBase=bindCommercial;
async function confirmBudgetClient(){const budget=quotesModule.active;if(!budget||budget.kind!=='budget'||!['draft','inReview','validated'].includes(budget.status))return;if(!confirm(`Confirmer que le client accepte ${budget.number} ?\n\nLe budget sera figé et pourra ensuite être converti manuellement en devis. Il ne sera pas intégré au chiffre d’affaires.`))return;try{const updated=await api(`/api/v1/quotes/${encodeURIComponent(budget.id)}/status`,{method:'POST',body:JSON.stringify({version:budget.version,status:'clientConfirmed'})});updateQuoteLocal(updated);render();toast('Budget confirmé par le client. La conversion en devis est maintenant disponible.')}catch(error){toast(apiMessage(error))}}
bindCommercial=function(){bindCommercialSynopticBase();const commercialDocument=quotesModule.active,actions=document.querySelector('.quote-workspace-page .page-title .actions');if(!commercialDocument||!actions||!can('quote.manage'))return;if(commercialDocument.kind==='budget'){actions.querySelector('[data-budget-convert]')?.remove();actions.querySelector('[data-quote-status]')?.remove();if(['draft','inReview','validated'].includes(commercialDocument.status))actions.insertAdjacentHTML('afterbegin','<button class="primary-button" data-budget-client-confirm>Confirmer le budget client</button>');if(commercialDocument.status==='clientConfirmed')actions.insertAdjacentHTML('afterbegin','<button class="primary-button" data-budget-convert>Convertir en devis</button>');actions.querySelector('[data-budget-client-confirm]')?.addEventListener('click',confirmBudgetClient);actions.querySelector('[data-budget-convert]')?.addEventListener('click',convertBudgetToQuote)}const methodLabels={manual:'Saisie manuelle',planning:'Créé depuis le planning',clientPlanningImport:'Planning client analysé par PlanyBot',budgetConversion:'Converti depuis un budget'};const subtitle=document.querySelector('.quote-workspace-page .page-title p');if(subtitle&&commercialDocument.creationMethod)subtitle.textContent+=` · ${methodLabels[commercialDocument.creationMethod]||commercialDocument.creationMethod}`}
const bindCommercialProjectSynopticBase=bindCommercial;
bindCommercial=function(){bindCommercialProjectSynopticBase();if(can('quote.manage')){document.querySelectorAll('[data-quote-from-planning]').forEach(anchor=>{if(anchor.parentElement?.querySelector('[data-quote-from-client-planning]'))return;anchor.insertAdjacentHTML('afterend',`<button class="secondary-button" data-quote-from-client-planning="${esc(anchor.dataset.quoteFromPlanning)}">Créer un devis depuis un planning client</button>`)});const projectId=(location.hash.match(/^#project-(.+)$/)||[])[1];if(projectId){const create=document.querySelector('[data-quote-create="quote"]');if(create&&!create.parentElement?.querySelector('[data-quote-from-client-planning]'))create.insertAdjacentHTML('afterend',`<button class="secondary-button" data-quote-from-client-planning="${esc(projectId)}">Devis depuis planning client</button>`)}document.querySelectorAll('[data-quote-from-client-planning]').forEach(button=>button.onclick=()=>{openQuoteCreateDrawer(button.dataset.quoteFromClientPlanning,'quote');activeStockEditor.creationMethod='clientPlanningImport';stockDrawerTitle.textContent='Créer un devis depuis un planning client';const info=stockDrawerBody.querySelector('.drawer-info span');if(info)info.textContent='Le devis sera créé en brouillon, puis PlanyBot analysera le fichier sans créer de réservation.'})}const active=quotesModule.active,importButton=document.querySelector('[data-quote-import]');if(active?.kind==='quote'&&active.status==='draft'&&active.creationMethod==='clientPlanningImport'&&importButton){const replacement=importButton.cloneNode(true);replacement.textContent='Importer le planning client';replacement.title='Analyser Excel, CSV ou PDF avec PlanyBot sans créer de réservation';importButton.replaceWith(replacement);replacement.onclick=openDraftQuoteClientPlanningImport}}

const submitQuoteCreateSynopticBase=submitQuoteCreate;
submitQuoteCreate=async function(event){if(activeStockEditor?.kind!=='quoteCreate'||!activeStockEditor.creationMethod)return submitQuoteCreateSynopticBase(event);event.preventDefault();const data=new FormData(stockDrawerForm),form=Object.fromEntries(data),editor=activeStockEditor;stockDrawerSubmit.disabled=true;stockDrawerError.hidden=true;try{const quote=await api('/api/v1/quotes',{method:'POST',headers:{'Idempotency-Key':editor.idempotencyKey},body:JSON.stringify({projectId:editor.project.id,siteId:form.siteId||undefined,contactId:form.contactId||undefined,kind:'quote',creationMethod:'clientPlanningImport',title:form.title,taxDate:form.taxDate})});updateQuoteLocal(quote);stockDrawerDirty=false;stockDrawerBackdrop.hidden=true;location.hash=`quote-${quote.id}`;render();toast('Devis brouillon créé. Importez maintenant le planning client avec PlanyBot.');setTimeout(openDraftQuoteClientPlanningImport,0)}catch(error){if(error.code==='FISCAL_PROFILE_INCOMPLETE')showQuoteFiscalBlocker(error);else{stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}}finally{stockDrawerSubmit.disabled=false}};

function openDraftQuoteClientPlanningImport(){const quote=quotesModule.active;if(!quote||quote.kind!=='quote'||quote.status!=='draft'||quote.creationMethod!=='clientPlanningImport')return toast('Ce parcours est réservé à un devis brouillon créé depuis un planning client.');const project=find(state.projects,quote.projectId);activeStockEditor={kind:'quoteClientPlanningImport',quote,lines:quote.lines,idempotencyKey:uid('quote-client-plan-'),stage:'upload',pendingFile:null,analysis:null,guideConversationId:null,guideMessages:[{role:'assistant',content:'Déposez le planning client. Je vais extraire les prestations, dates et volumes. Vous validerez les correspondances avant toute écriture dans le devis. Aucune réservation ne sera créée.'}]};stockDrawerEyebrow.textContent='PROJET → DEVIS · PLANYBOT';stockDrawerTitle.textContent='Importer le planning client';stockDrawerSubmit.hidden=false;stockDrawerSubmit.disabled=true;stockDrawerSubmit.textContent='Sélectionnez un fichier';stockDrawerError.hidden=true;stockDrawerBody.innerHTML=`<div class="drawer-info"><strong>${esc(project?.name||'Projet')}</strong><span>Analyse commerciale uniquement : aucune réservation planning ne sera créée.</span></div><label class="client-planning-dropzone" data-client-planning-dropzone tabindex="0"><input type="file" hidden accept=".xlsx,.csv,.pdf,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv" data-client-planning-file><span class="client-planning-drop-icon">⇧</span><strong>Glissez le planning client ici</strong><span>Excel (.xlsx), CSV ou PDF texte · 5 Mo maximum</span><button type="button" class="secondary-button" data-client-file-picker>Choisir un fichier</button><small data-client-file-name>Aucun fichier sélectionné</small></label><ol class="client-planning-steps"><li class="active">1. Importer</li><li>2. Analyser</li><li>3. Vérifier les prestations</li><li>4. Créer les lignes du devis</li></ol><div class="drawer-info subtle"><strong>Tarifs automatiques</strong><span>Projet dédié, puis grille client, puis catalogue générique. Le prix n’est jamais inventé par PlanyBot.</span></div>${clientPlanningGuideMarkup()}`;stockDrawerBackdrop.hidden=false;stockDrawerDirty=false;stockDrawerForm.onsubmit=analyzeClientPlanningFile;bindClientPlanningGuide();const input=stockDrawerBody.querySelector('[data-client-planning-file]'),dropzone=stockDrawerBody.querySelector('[data-client-planning-dropzone]');input.addEventListener('change',()=>selectClientPlanningFile(input.files[0]));stockDrawerBody.querySelector('[data-client-file-picker]').addEventListener('click',()=>input.click());for(const name of ['dragenter','dragover'])dropzone.addEventListener(name,event=>{event.preventDefault();dropzone.classList.add('is-dragging')});for(const name of ['dragleave','drop'])dropzone.addEventListener(name,event=>{event.preventDefault();dropzone.classList.remove('is-dragging')});dropzone.addEventListener('drop',event=>selectClientPlanningFile(event.dataTransfer.files[0]));dropzone.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();input.click()}});setTimeout(()=>dropzone.focus(),0)}

const renderClientPlanningComparisonSynopticBase=renderClientPlanningComparison;
renderClientPlanningComparison=function(analysis){if(activeStockEditor?.kind!=='quoteClientPlanningImport')return renderClientPlanningComparisonSynopticBase(analysis);const editor=activeStockEditor,quote=editor.quote,resources=state.resources.filter(resource=>resource.active!==false&&(!quote.siteId||resource.siteId===quote.siteId));editor.analysis=analysis;editor.stage='commercial-review';stockDrawerTitle.textContent=`Prestations détectées · ${analysis.fileName}`;stockDrawerSubmit.hidden=false;stockDrawerSubmit.disabled=false;stockDrawerSubmit.textContent='Ajouter au devis';stockDrawerBody.innerHTML=`<div class="drawer-info client-planning-summary"><strong>Analyse terminée — aucune réservation créée</strong><span>${analysis.rows.length} ligne(s) détectée(s). Sélectionnez uniquement les prestations commerciales à conserver.</span></div><div class="client-planning-compare">${analysis.rows.map(row=>{const choices=[...new Set([row.suggestedResourceId,...(row.resourceCandidates||[]).map(item=>item.id),...resources.map(item=>item.id)].filter(Boolean))].map(id=>find(state.resources,id)).filter(Boolean);return`<article class="client-planning-compare-row ${choices.length?'matched':'unmatched'}" data-client-planning-row="${esc(row.rowNumber)}"><header><label class="client-plan-check"><input type="checkbox" data-commercial-row ${choices.length?'checked':''}> Ajouter au devis</label><span class="match-badge ${choices.length?'matched':'unmatched'}">${choices.length?'Ressource proposée':'Correspondance requise'}</span></header><strong>${esc(row.label)}</strong><small>${esc(row.startDate)} → ${esc(row.endDate)} · ${esc(row.durationDays)} jour(s)</small><div class="form-grid"><label>Prestation / ressource<select data-commercial-resource><option value="">Ligne libre à qualifier</option>${choices.map(resource=>`<option value="${esc(resource.id)}" ${resource.id===row.suggestedResourceId?'selected':''}>${esc(resource.name)}</option>`).join('')}</select></label><label>Libellé<input data-commercial-label value="${esc(row.label)}" maxlength="200" required></label><label>Quantité (jours)<input data-commercial-days type="number" min="1" max="3660" value="${esc(row.durationDays||1)}" required></label></div></article>`}).join('')}</div><p class="client-planning-privacy">PlanyBot prépare les lignes ; vous confirmez. Les tarifs sont résolus côté serveur et aucune réservation n’est créée.</p>${clientPlanningGuideMarkup()}`;bindClientPlanningGuide();stockDrawerForm.onsubmit=applyClientPlanningQuoteLines;setTimeout(()=>stockDrawerBody.querySelector('[data-commercial-row]')?.focus(),0)};

const renderClientPlanningClarificationBase=renderClientPlanningComparison;
renderClientPlanningComparison=function(analysis){renderClientPlanningClarificationBase(analysis);if(!activeStockEditor?.analysis)return;activeStockEditor.analysis.version ||= 1;for(const row of analysis.rows.filter(value=>['ambiguous','unmatched'].includes(value.matchStatus))){const article=stockDrawerBody.querySelector(`[data-client-planning-row="${CSS.escape(String(row.rowNumber))}"]`);if(!article)continue;article.dataset.matchStatus=row.matchStatus;article.insertAdjacentHTML('beforeend',`<label class="client-planning-resolution">Pourquoi cette correction ?<input data-plan-resolution maxlength="500" placeholder="Ex. salle confirmée avec l’assistante planning" required></label>`)} };
function clientPlanningCorrections(){return[...stockDrawerBody.querySelectorAll('[data-client-planning-row]')].filter(row=>row.querySelector('[data-plan-row]')?.checked&&['ambiguous','unmatched'].includes(row.dataset.matchStatus)).map(row=>({rowNumber:Number(row.dataset.clientPlanningRow),suggestedQuoteLineId:row.querySelector('[data-plan-line]').value,suggestedResourceId:row.querySelector('[data-plan-resource]').value,startDate:row.querySelector('[data-plan-date]').value,durationDays:Number(row.querySelector('[data-plan-duration]').value),startTime:row.querySelector('[data-plan-start]').value||'09:00',endTime:row.querySelector('[data-plan-end]').value||'18:00',resolutionNote:row.querySelector('[data-plan-resolution]').value,confirmed:true}))}
async function saveClientPlanningCorrections(){const editor=activeStockEditor,corrections=clientPlanningCorrections();if(!editor?.analysis||!corrections.length)return;const signature=JSON.stringify(corrections);editor.revisionKeys ||= new Map();const key=editor.revisionKeys.get(signature)||uid('client-planning-revision-');editor.revisionKeys.set(signature,key);editor.analysis=await api(`/api/v1/quotes/${encodeURIComponent(editor.quote.id)}/client-planning/${encodeURIComponent(editor.analysis.id)}/revisions`,{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify({importVersion:editor.analysis.version||1,corrections})});for(const row of stockDrawerBody.querySelectorAll('[data-client-planning-row]'))if(corrections.some(value=>value.rowNumber===Number(row.dataset.clientPlanningRow)))row.dataset.matchStatus='confirmed';addClientPlanningGuideMessage('assistant',`${corrections.length} correction(s) humaine(s) confirmée(s) et historisée(s). Je peux maintenant vérifier les disponibilités.`)}
function directClientPlanningCorrections(){const editor=activeStockEditor;return[...stockDrawerBody.querySelectorAll('[data-client-planning-row]')].filter(row=>row.querySelector('[data-commercial-row]')?.checked&&['ambiguous','unmatched'].includes(row.dataset.matchStatus)).map(row=>{const source=editor.analysis.rows.find(value=>Number(value.rowNumber)===Number(row.dataset.clientPlanningRow));return{rowNumber:Number(row.dataset.clientPlanningRow),suggestedResourceId:row.querySelector('[data-commercial-resource]').value,label:row.querySelector('[data-commercial-label]').value,startDate:source.startDate,durationDays:Number(row.querySelector('[data-commercial-days]').value),startTime:source.startTime||'09:00',endTime:source.endTime||'18:00',resolutionNote:row.querySelector('[data-plan-resolution]').value,confirmed:true}})}
async function saveDirectClientPlanningCorrections(){const editor=activeStockEditor,corrections=directClientPlanningCorrections();if(!corrections.length)return;const signature=JSON.stringify(corrections);editor.revisionKeys ||= new Map();const key=editor.revisionKeys.get(signature)||uid('client-planning-revision-');editor.revisionKeys.set(signature,key);editor.analysis=await api(`/api/v1/quotes/${encodeURIComponent(editor.quote.id)}/client-planning/${encodeURIComponent(editor.analysis.id)}/revisions`,{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify({importVersion:editor.analysis.version||1,corrections})});for(const row of stockDrawerBody.querySelectorAll('[data-client-planning-row]'))if(corrections.some(value=>value.rowNumber===Number(row.dataset.clientPlanningRow)))row.dataset.matchStatus='confirmed';addClientPlanningGuideMessage('assistant',`${corrections.length} correspondance(s) confirmée(s). Les lignes du devis peuvent maintenant être créées.`)}
const previewQuotePlanningConversionClarificationBase=previewQuotePlanningConversion;
previewQuotePlanningConversion=async function(event){if(activeStockEditor?.analysis&&activeStockEditor.kind!=='quoteClientPlanningImport'){event.preventDefault();try{await saveClientPlanningCorrections()}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false;return}}return previewQuotePlanningConversionClarificationBase(event)};

async function applyClientPlanningQuoteLines(event){event.preventDefault();const editor=activeStockEditor,quote=editor.quote;stockDrawerSubmit.disabled=true;stockDrawerError.hidden=true;try{await saveDirectClientPlanningCorrections();const items=[...stockDrawerBody.querySelectorAll('[data-client-planning-row]')].filter(row=>row.querySelector('[data-commercial-row]').checked).map(row=>{const sourceId=row.querySelector('[data-commercial-resource]').value,days=Number(row.querySelector('[data-commercial-days]').value);return{rowNumber:Number(row.dataset.clientPlanningRow),sourceType:'resource',sourceId,category:'room',section:'Planning client',label:row.querySelector('[data-commercial-label]').value,unit:'jour',quantityMilli:String(BigInt(days)*1000n),requestedDurationDays:days}});if(!items.length)throw new Error('Sélectionnez au moins une prestation.');if(items.some(item=>!item.sourceId))throw new Error('Choisissez une ressource pour chaque prestation sélectionnée.');const updated=await api(`/api/v1/quotes/${encodeURIComponent(quote.id)}/client-planning/apply-lines`,{method:'POST',headers:{'Idempotency-Key':editor.idempotencyKey},body:JSON.stringify({version:quote.version,quoteVersionId:quote.currentVersionId,clientPlanningImportId:editor.analysis.id,items})});updateQuoteLocal(updated);stockDrawerDirty=false;stockDrawerBackdrop.hidden=true;render();toast(`${items.length} prestation(s) ajoutée(s) au devis. Aucune réservation créée.`)}catch(error){stockDrawerError.textContent=apiMessage(error);stockDrawerError.hidden=false}finally{stockDrawerSubmit.disabled=false}}

function planningQuantityLabel(value,unit){const quantity=Number(BigInt(value||'0'))/1000;return`${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(quantity)} ${esc(unit||'unité')}`}
function planningControlStateLabel(stateValue){return{unplanned:'À planifier',partiallyPlanned:'Partiellement planifié',compliant:'Conforme',overPlanned:'Dépassement',nonApplicable:'Non applicable'}[stateValue]||stateValue}
function acceptedQuoteForPlanning(){return quotesModule.items.find(value=>value.id===activePlanningQuoteId&&value.kind==='quote'&&value.status==='accepted')||null}
function acceptedQuotePlanningMarkup(control,quote){if(!control)return`<aside class="planning-quote-control" aria-busy="true"><p class="eyebrow">PLANYBOT</p><h2>Contrôle du devis</h2><p>Calcul des quantités planifiées…</p></aside>`;const actionable=control.items.filter(item=>item.planifiable),firstIssue=actionable.find(item=>item.state==='overPlanned')||actionable.find(item=>['unplanned','partiallyPlanned'].includes(item.state)),message=firstIssue?.state==='overPlanned'?`${firstIssue.label} dépasse le devis de ${planningQuantityLabel(firstIssue.differenceQuantityMilli,firstIssue.unit)}. Le devis complémentaire brouillon est synchronisé.`:firstIssue?`${firstIssue.label} : il reste ${planningQuantityLabel(firstIssue.remainingQuantityMilli,firstIssue.unit)} à positionner.`:'Toutes les prestations planifiables sont réparties.',currencyExponent=Number(quote.fiscalSnapshot?.currencyExponent??2);return`<aside class="planning-quote-control" aria-label="Contrôle PlanyBot du devis"><header><div><p class="eyebrow">PLANYBOT · DEVIS DU PROJET</p><h2>${esc(quote.number)}</h2></div><button class="icon-button" type="button" data-planning-quote-close aria-label="Fermer le contrôle du devis">×</button></header><div class="planning-control-progress"><strong>Planification du devis : ${esc(control.progressPercent)} %</strong><span><i style="width:${Math.min(100,control.progressPercent)}%"></i></span></div><div class="planning-control-message"><b>PlanyBot</b><p>${esc(message)}</p></div>${control.complementaryDraft?`<a class="planning-complement-link" href="#quote-${esc(control.complementaryDraft.id)}"><strong>Devis complémentaire mis à jour</strong><span>${esc(control.complementaryDraft.number)} · ${control.complementaryDraft.lineCount} ligne(s)</span></a>`:''}<div class="planning-control-items">${control.items.map(item=>`<article class="state-${item.state}"><header><strong>${esc(item.label)}</strong><span>${planningControlStateLabel(item.state)}</span></header>${item.planifiable?`<p><b>${planningQuantityLabel(item.plannedQuantityMilli,item.unit)}</b> / ${planningQuantityLabel(item.soldQuantityMilli,item.unit)}</p><small>${item.state==='overPlanned'?`+ ${planningQuantityLabel(item.differenceQuantityMilli,item.unit)} hors devis${BigInt(item.estimatedOverageNetHt||'0')>0n?` · ${formatMinorExact(item.estimatedOverageNetHt,item.currency,currencyExponent)} HT`:''}`:item.state==='compliant'?'Quantité conforme':`${planningQuantityLabel(item.remainingQuantityMilli,item.unit)} restant`}</small>`:'<p>Cette prestation ne crée pas de réservation.</p>'}</article>`).join('')}</div><button class="primary-button" type="button" data-planning-validate ${control.entirelyPlanned&&can('planning.validate')?'':'disabled'}>${control.status==='validated'?'Planification validée':'Valider la planification'}</button><p class="planning-control-rule">Les réservations restent opérationnelles. Tout dépassement du vendu alimente automatiquement un seul devis complémentaire brouillon.</p></aside>`}
async function refreshAcceptedQuotePlanning(){const quote=acceptedQuoteForPlanning(),aside=document.querySelector('.planning-quote-control');if(!quote||!aside)return;try{planningQuoteControl=await api(`/api/v1/quotes/${encodeURIComponent(quote.id)}/planning-control`);aside.outerHTML=acceptedQuotePlanningMarkup(planningQuoteControl,quote);bindAcceptedQuotePlanningActions()}catch(error){aside.innerHTML=`<p class="eyebrow">PLANYBOT</p><h2>Contrôle indisponible</h2><p>${esc(apiMessage(error))}</p>`}}
function bindAcceptedQuotePlanningActions(){document.querySelector('[data-planning-quote-close]')?.addEventListener('click',()=>{activePlanningQuoteId='';planningQuoteControl=null;render()});document.querySelector('[data-planning-validate]')?.addEventListener('click',validateAcceptedQuotePlanning);document.querySelector('[data-planning-amendment]')?.addEventListener('click',preparePlanningAmendment)}
