const actualsModule={pending:[],records:[],loading:false,error:'',companyId:null,eventsBound:false};
const actualDateTime=value=>{const date=new Date(value);return Number.isNaN(date.getTime())?'':new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const actualQuantity=value=>{const raw=String(value||'0'),negative=raw.startsWith('-'),digits=(negative?raw.slice(1):raw).padStart(4,'0'),whole=digits.slice(0,-3).replace(/^0+(?=\d)/,''),fraction=digits.slice(-3).replace(/0+$/,'');return`${negative?'-':''}${whole}${fraction?`,${fraction}`:''}`};
const actualInputQuantity=value=>actualQuantity(value).replace(',','.');
async function loadActuals(){if(apiMode!=='api'||!state.user||!can('actual.read'))return;actualsModule.loading=true;actualsModule.error='';try{const[pending,records]=await Promise.all([api('/api/v1/actuals/pending?pageSize=200'),api('/api/v1/actuals?pageSize=200')]);actualsModule.pending=listItems(pending);actualsModule.records=listItems(records);actualsModule.companyId=state.user.companyId}catch(error){actualsModule.error=apiMessage(error)}finally{actualsModule.loading=false;if(location.hash.slice(1)==='actuals')render()}}
function actualsPage(){if(actualsModule.loading)return`<section class="page actuals-page"><div class="stock-state" role="status">Chargement des réalisations…</div></section>`;if(actualsModule.error)return`<section class="page actuals-page"><div class="stock-state error" role="alert"><h1>Chargement impossible</h1><p>${esc(actualsModule.error)}</p><button class="secondary-button" data-actual-retry>Réessayer</button></div></section>`;const pending=actualsModule.pending,records=actualsModule.records;return`<section class="page actuals-page">${title('Réalisations à confirmer','Validez le temps et la quantité réellement exécutés. La lecture de cette file ne modifie aucune donnée.')}<div class="stats actuals-kpis"><article class="card stat"><div class="stat-top">À confirmer</div><div class="stat-value">${pending.length}</div></article><article class="card stat"><div class="stat-top">Historisées</div><div class="stat-value">${records.length}</div></article><article class="card stat"><div class="stat-top">Avec écart</div><div class="stat-value">${records.filter(value=>value.reconciliation?.state!=='compliant').length}</div></article></div><article class="card actuals-section"><header><div><p class="eyebrow">FILE OPÉRATIONNELLE</p><h2>Sessions terminées</h2></div><button class="secondary-button" data-actual-retry>Actualiser</button></header><div class="actuals-list">${pending.map(value=>`<article><div><strong>${esc(value.title)}</strong><span>${esc(find(state.projects,value.projectId)?.name||value.projectId)} · ${esc(new Date(value.startsAt).toLocaleString('fr-FR'))}</span></div><dl><div><dt>Prévu</dt><dd>${actualQuantity(value.quantityMilli)} ${esc(value.unit)}</dd></div><div><dt>Fin</dt><dd>${esc(new Date(value.endsAt).toLocaleDateString('fr-FR'))}</dd></div></dl>${can('actual.confirm')?`<button class="primary-button" data-actual-confirm="${esc(value.reservationId)}">Confirmer le réalisé</button>`:'<span class="pill">Lecture seule</span>'}</article>`).join('')||'<p class="empty-cell">Toutes les sessions terminées sont confirmées.</p>'}</div></article><article class="card actuals-section"><header><div><p class="eyebrow">HISTORIQUE APPEND-ONLY</p><h2>Réalisations enregistrées</h2></div></header><div class="actuals-list history">${records.map(value=>`<article><div><strong>${esc(value.reservation?.title||find(state.bookings,value.reservationId)?.title||value.reservationId)}</strong><span>Révision ${value.currentRevision?.revisionNumber||1} · ${esc(find(state.projects,value.projectId)?.name||value.projectId)}</span></div><dl><div><dt>Réalisé</dt><dd>${actualQuantity(value.currentRevision?.quantityMilli)} ${esc(value.currentRevision?.unit||'')}</dd></div><div><dt>Écart planning</dt><dd>${actualQuantity(value.reconciliation?.plannedDeviationQuantityMilli)} ${esc(value.currentRevision?.unit||'')}</dd></div></dl><span class="actual-state state-${esc(value.reconciliation?.state||'compliant')}">${value.reconciliation?.state==='compliant'?'Conforme':value.reconciliation?.state==='overActual'?'Dépassement':'Sous-réalisation'}</span>${can('actual.confirm')?`<button class="secondary-button" data-actual-correct="${esc(value.id)}">Corriger</button>`:''}</article>`).join('')||'<p class="empty-cell">Aucune réalisation historisée.</p>'}</div></article><dialog class="actual-dialog" data-actual-dialog aria-labelledby="actual-dialog-title"><form method="dialog" data-actual-form><header><div><p class="eyebrow">RÉALISATION</p><h2 id="actual-dialog-title" data-actual-title>Confirmer le réalisé</h2></div><button type="button" class="icon-button" data-actual-close aria-label="Fermer">×</button></header><input name="targetId" type="hidden"><input name="mode" type="hidden"><input name="version" type="hidden"><div class="form-grid"><label>Début réel<input name="startsAt" type="datetime-local" required></label><label>Fin réelle<input name="endsAt" type="datetime-local" required></label></div><div class="form-grid"><label>Quantité réelle<input name="quantity" type="number" min="0" max="9007199254740" step="0.001" required></label><label>Unité du planning<input name="unit" readonly aria-readonly="true"></label></div><label>Motif de l’écart ou de la correction<textarea name="reason" maxlength="1000" placeholder="Obligatoire si la valeur réelle diffère du planning"></textarea></label><div class="conflict-alert" data-actual-error hidden></div><footer><button type="button" class="secondary-button" data-actual-close>Annuler</button><button class="primary-button">Enregistrer la réalisation</button></footer></form></dialog></section>`}
function openActualDialog(mode,idValue){const dialog=document.querySelector('[data-actual-dialog]'),form=dialog?.querySelector('[data-actual-form]');if(!dialog||!form)return;const source=mode==='confirm'?actualsModule.pending.find(value=>value.reservationId===idValue):actualsModule.records.find(value=>value.id===idValue),revision=source?.currentRevision||source;if(!source||!revision)return;form.reset();form.elements.mode.value=mode;form.elements.targetId.value=idValue;form.elements.version.value=mode==='confirm'?source.reservationVersion:source.version;form.elements.startsAt.value=actualDateTime(revision.startsAt);form.elements.endsAt.value=actualDateTime(revision.endsAt);form.elements.quantity.value=actualInputQuantity(revision.quantityMilli);form.elements.unit.value=revision.unit;form.querySelector('[data-actual-title]').textContent=mode==='confirm'?'Confirmer le réalisé':'Corriger la réalisation';dialog.showModal();setTimeout(()=>form.elements.startsAt.focus(),0)}
async function submitActual(event){event.preventDefault();const form=event.currentTarget,error=form.querySelector('[data-actual-error]'),mode=form.elements.mode.value,targetId=form.elements.targetId.value,reason=form.elements.reason.value.trim();error.hidden=true;try{const payload={startsAt:new Date(form.elements.startsAt.value).toISOString(),endsAt:new Date(form.elements.endsAt.value).toISOString(),quantityMilli:decimalToScaledString(form.elements.quantity.value,3,'La quantité réelle')};if(mode==='confirm')Object.assign(payload,{reservationVersion:Number(form.elements.version.value),...(reason?{deviationReason:reason}:{})});else Object.assign(payload,{actualVersion:Number(form.elements.version.value),correctionReason:reason});await api(mode==='confirm'?`/api/v1/reservations/${encodeURIComponent(targetId)}/actual/confirm`:`/api/v1/actuals/${encodeURIComponent(targetId)}/revisions`,{method:'POST',headers:{'Idempotency-Key':uid(`actual-${mode}-`)},body:JSON.stringify(payload)});form.closest('dialog').close();await loadActuals();toast(mode==='confirm'?'Réalisation confirmée et historisée.':'Correction historisée dans une nouvelle révision.')}catch(apiError){error.textContent=apiMessage(apiError);error.hidden=false}}
function bindActuals(){document.querySelectorAll('[data-actual-retry]').forEach(button=>button.onclick=loadActuals);document.querySelectorAll('[data-actual-confirm]').forEach(button=>button.onclick=()=>openActualDialog('confirm',button.dataset.actualConfirm));document.querySelectorAll('[data-actual-correct]').forEach(button=>button.onclick=()=>openActualDialog('correct',button.dataset.actualCorrect));document.querySelectorAll('[data-actual-close]').forEach(button=>button.onclick=()=>button.closest('dialog')?.close());document.querySelector('[data-actual-form]')?.addEventListener('submit',submitActual);const dialog=document.querySelector('[data-actual-dialog]');if(dialog)dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()})}
function startActualEvents(){if(actualsModule.eventsBound||!eventStream)return;actualsModule.eventsBound=true;eventStream.addEventListener('invalidation',event=>{let payload={};try{payload=JSON.parse(event.data)||{}}catch{}if(!String(payload.type||'').startsWith('actual.')||payload.companyId!==state.user?.companyId)return;clearTimeout(sseTimer);sseTimer=setTimeout(async()=>{await loadActuals();toast('Réalisations actualisées.')},250)})}
const renderActualsBase=render;render=function(){const route=typeof location==='undefined'?'':location.hash.slice(1);document.querySelectorAll('[data-actual-nav]').forEach(link=>link.hidden=!state.user||!can('actual.read'));if(!state.user||route!=='actuals')return renderActualsBase();loginScreen.hidden=true;pageCrumb.textContent='Réalisations';quickCreate.hidden=true;document.querySelectorAll('[data-route]').forEach(link=>{const active=link.dataset.route==='actuals';link.classList.toggle('active',active);link.toggleAttribute('aria-current',active)});if(!can('actual.read')){app.innerHTML='<section class="page"><div class="stock-state error" role="alert"><h1>Accès refusé</h1><p>Votre rôle ne permet pas de consulter les réalisations.</p></div></section>';return}if(actualsModule.companyId!==state.user.companyId&&!actualsModule.loading){actualsModule.companyId=state.user.companyId;actualsModule.pending=[];actualsModule.records=[];loadActuals()}app.innerHTML=actualsPage();bindActuals();startActualEvents()};
const switchActualContextBase=switchOrganization;switchOrganization=async function(companyId){actualsModule.pending=[];actualsModule.records=[];actualsModule.companyId=null;actualsModule.eventsBound=false;return switchActualContextBase(companyId)};
if(typeof document!=='undefined'){
  bindUniversalSearch();
  if(typeof MutationObserver!=='undefined'&&modalBackdrop)new MutationObserver(()=>{if(modalBackdrop.hidden)releasePlanningPresence()}).observe(modalBackdrop,{attributes:true,attributeFilter:['hidden']});
  window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!=='planning')releasePlanningPresence()});
  bookingForm?.elements?.timeGranularity?.addEventListener('change',event=>{bookingForm.dataset.timePolicyTouched='true';const granularity=event.target.value;bookingForm.elements.start.value=snapPlanningTime(bookingForm.elements.start.value,granularity,'start');bookingForm.elements.end.value=snapPlanningTime(bookingForm.elements.end.value,granularity,'end')});
  bookingForm?.addEventListener('submit',()=>{if(bookingForm.dataset.timePolicyTouched!=='true')return;const granularity=bookingForm.elements.timeGranularity?.value||'day';bookingForm.elements.start.value=snapPlanningTime(bookingForm.elements.start.value,granularity,'start');bookingForm.elements.end.value=snapPlanningTime(bookingForm.elements.end.value,granularity,'end')},{capture:true});
}
